// Vanilla Minecraft 1.16.1 data (registries, block states, MC enums), generated by
// datagen/src/mc.ts. Loaded with fs so the same code works from src/ and dist/.
import { readFileSync } from 'node:fs';

/** [block name, first block-state id, properties as [name, values][] in state order] */
export type BlockRow = [name: string, firstId: number, props?: [name: string, values: string[]][]];

export interface McData {
  minecraft: string;
  generatedBy: string;
  /** Registry name -> entries in raw-id order (names without the `minecraft:` prefix). */
  registries: {
    item: string[];
    entity_type: string[];
    mob_effect: string[];
    enchantment: string[];
    potion: string[];
    menu: string[];
    villager_type: string[];
    villager_profession: string[];
  };
  blocks: BlockRow[];
  enums: {
    Hand: string[];
    EquipmentSlot: string[];
    EntityPose: string[];
    DyeColor: string[];
    BoatType: string[];
    DragonPhase: string[];
  };
  /** Entity type name -> the kind of extra data its ENTITY_ADD/MOB_STATE records carry. */
  entityKinds: Record<string, string>;
}

export const MC_DATA: McData = JSON.parse(readFileSync(new URL('../data/mc_1_16_1.json', import.meta.url), 'utf8'));
